import sys
from itertools import permutations

def solve():
    assignment = {}
    used_labels = set()
    used_diffs = set()

    # Order vertices by degree (highest first for better pruning)
    vertex_order = sorted(range(12), key=lambda v: -len([e for e in edges if v in e]))

    def backtrack(idx):
        if idx == 12:
            return True

        v = vertex_order[idx]

        for label in range(22):
            if label in used_labels:
                continue

            # Check all edges involving v where neighbor is already assigned
            valid = True
            new_diffs = []
            for neighbor in [e[1] if e[0]==v else e[0] for e in edges if v in e]:
                if neighbor in assignment:
                    d = abs(label - assignment[neighbor])
                    if d == 0 or d > 21 or d in used_diffs or d in new_diffs:
                        valid = False
                        break
                    new_diffs.append(d)

            if valid:
                assignment[v] = label
                used_labels.add(label)
                for d in new_diffs:
                    used_diffs.add(d)

                if backtrack(idx + 1):
                    return True

                del assignment[v]
                used_labels.remove(label)
                for d in new_diffs:
                    used_diffs.remove(d)

        return False

    if backtrack(0):
        result = [assignment[i] for i in range(12)]
        return result
    return None

print("Solving with backtracking...")
sol = solve()
if sol:
    print(f"Solution found: {sol}")
